public strictfp class DeterministicPhysicsEngine {

    public double calculateTrajectoryVector(double velocity, double angleRadians) {
        // Both StrictMath and the strictfp class context guarantee
        // that trigonometric operations resolve identically across architectures.
        double xComponent = velocity * StrictMath.cos(angleRadians);
        double yComponent = velocity * StrictMath.sin(angleRadians);

        return StrictMath.hypot(xComponent, yComponent);
    }
}
